WITH head AS MATERIALIZED (
 SELECT coalesce((SELECT revision FROM public.inbox_inbound_heads WHERE org_id='8316ab64-2b3b-49fa-bc3a-05428556de7b' AND conversation_id='26916424-abc1-49ac-9abe-d191d4700929'),0)::text AS revision
), history AS MATERIALIZED (
 SELECT id,created_at::text AS created_at_raw,inbox_inbound_revision::text AS inbound_revision,direction,read_at::text AS read_at_raw
 FROM public.messages WHERE org_id='8316ab64-2b3b-49fa-bc3a-05428556de7b' AND conversation_id='26916424-abc1-49ac-9abe-d191d4700929' AND channel='sms'
 ORDER BY created_at DESC,id DESC LIMIT 50
) SELECT json_build_object('head',(SELECT revision FROM head),'history',coalesce((SELECT json_agg(row_to_json(h)) FROM history h),'[]'::json));

