WITH eligible AS MATERIALIZED (
 SELECT id FROM public.messages WHERE org_id='8316ab64-2b3b-49fa-bc3a-05428556de7b' AND conversation_id='26916424-abc1-49ac-9abe-d191d4700929' AND channel='sms' AND direction='inbound' AND read_at IS NULL AND inbox_inbound_revision <= 451::bigint
 ORDER BY id LIMIT 200 FOR UPDATE
), changed AS (
 UPDATE public.messages m SET read_at=statement_timestamp() FROM eligible e WHERE m.id=e.id
 AND m.org_id='8316ab64-2b3b-49fa-bc3a-05428556de7b' AND m.conversation_id='26916424-abc1-49ac-9abe-d191d4700929' AND m.channel='sms' AND m.direction='inbound' AND m.read_at IS NULL AND m.inbox_inbound_revision <= 451::bigint RETURNING m.id
) SELECT count(*) FROM changed;
